package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.time.YearMonth; import java.time.ZoneOffset; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @Service public class BudgetService{private final BudgetRepository budgets;private final FinanceTransactionRepository transactions;private final FinanceLedgerAccessService access;public BudgetService(BudgetRepository b,FinanceTransactionRepository t,FinanceLedgerAccessService x){budgets=b;transactions=t;access=x;}public Mono<BudgetView> save(UUID a,UUID l,CreateBudgetRequest q){if(q.amount().signum()<0)return Mono.error(new IllegalArgumentException("预算金额不能为负"));return access.requireEditor(a,l).then(budgets.findByLedgerIdAndCategoryIdAndMonth(l,q.categoryId(),q.month()).flatMap(old->budgets.save(new BudgetEntity(old.id(),l,old.ownerId(),q.categoryId(),q.month(),q.amount(),old.createdAt(),old.version()))).switchIfEmpty(budgets.save(new BudgetEntity(null,l,a,q.categoryId(),q.month(),q.amount(),Instant.now(),null)))).flatMap(this::withActual);}public Flux<BudgetView> list(UUID a,UUID l,YearMonth m){return access.access(a,l).flatMapMany(x->budgets.findAllByLedgerIdAndMonthOrderByCategoryIdAsc(l,m).flatMap(this::withActual));}private Mono<BudgetView> withActual(BudgetEntity b){Instant from=b.month().atDay(1).atStartOfDay().toInstant(ZoneOffset.UTC),to=b.month().plusMonths(1).atDay(1).atStartOfDay().toInstant(ZoneOffset.UTC);return transactions.findAllByLedgerIdAndOccurredAtGreaterThanEqualAndOccurredAtLessThanOrderByOccurredAtDesc(b.ledgerId(),from,to).filter(t->t.type()==TransactionType.EXPENSE&&b.categoryId().equals(t.categoryId())).map(FinanceTransactionEntity::amount).reduce(BigDecimal.ZERO,BigDecimal::add).map(actual->new BudgetView(b.id(),b.ledgerId(),b.categoryId(),b.month(),b.amount(),actual,b.amount().subtract(actual)));}}
